# /// script
# requires-python = ">=3.11"
# dependencies = ["pytest"]
# ///
import pytest

from req_diff import diff_pins, is_major_bump, parse_requirements, parse_uv_lock

HASHED_REQUIREMENTS = """\
#
# This file is autogenerated
#
ipykernel==6.31.0 \\
    --hash=sha256:aaa \\
    --hash=sha256:bbb
    # via -r requirements.in
Jupyter_Client==8.6.3 ; python_version >= "3.10" \\
    --hash=sha256:ccc
typing-extensions<4.11.0
"""

UV_LOCK = """\
version = 1

[[package]]
name = "ipython"
version = "8.39.0"

[[package]]
name = "ipython"
version = "9.14.1"

[[package]]
name = "positron"
source = { editable = "." }
"""


def test_parse_requirements_reads_hashed_pins_and_normalizes_names():
    assert parse_requirements(HASHED_REQUIREMENTS) == {
        "ipykernel": {"6.31.0"},
        "jupyter-client": {"8.6.3"},
    }


def test_parse_uv_lock_keeps_every_locked_version_and_skips_unversioned():
    assert parse_uv_lock(UV_LOCK) == {"ipython": {"8.39.0", "9.14.1"}}


@pytest.mark.parametrize(
    ("old", "new", "expected"),
    [
        ("6.31.0", "7.3.0", True),
        ("8.18.1", "8.39.0", False),
        ("0.2.3", "0.3.0", True),
        ("0.2.3", "0.2.9", False),
        ("2026.4", "2026.12", False),
        ("1.0", "1.0.post1", False),
    ],
)
def test_is_major_bump(old, new, expected):
    assert is_major_bump(old, new) is expected


def test_diff_pins_reports_changes_additions_and_removals():
    old = {"ipykernel": {"6.31.0"}, "comm": {"0.2.3"}, "gone": {"1.0"}}
    new = {"ipykernel": {"7.3.0"}, "comm": {"0.2.3"}, "added": {"2.0"}}
    assert diff_pins(old, new) == [
        ("added", "-", "2.0", False),
        ("gone", "1.0", "-", False),
        ("ipykernel", "6.31.0", "7.3.0", True),
    ]


def test_diff_pins_is_empty_for_identical_input():
    assert diff_pins({"a": {"1.0"}}, {"a": {"1.0"}}) == []
